// AdminCoach The whole admin card in one answer. Never a credential, only whether one is filed.
type AdminCoach struct {
	// Auth Whether a credential is filed, and whose. `unreadable` is its own state because it has a specific cause and a specific fix: ./data restored without its `secret`.
	Auth *struct {
		Account     *string              `json:"account,omitempty"`
		ConnectedAt *time.Time           `json:"connectedAt,omitempty"`
		State       *AdminCoachAuthState `json:"state,omitempty"`
		Type        *string              `json:"type,omitempty"`
	} `json:"auth,omitempty"`
	AuthMode *AdminCoachAuthMode `json:"authMode,omitempty"`
	BaseUrl  *string             `json:"baseUrl,omitempty"`

	// BoundUid The profile an instance credential bound itself to, once one has spent it.
	BoundUid *string `json:"boundUid,omitempty"`
	Caps     *struct {
		InstanceDaily   *int `json:"instanceDaily,omitempty"`
		PerProfileDaily *int `json:"perProfileDaily,omitempty"`
	} `json:"caps,omitempty"`
	Community *bool `json:"community,omitempty"`

	// DisabledByEnv COACH_DISABLED is set, so nothing the admin toggles matters.
	DisabledByEnv *bool `json:"disabledByEnv,omitempty"`
	Enabled       *bool `json:"enabled,omitempty"`
	JobsToday     *int  `json:"jobsToday,omitempty"`

	// KnownModels From the live check, when the provider could be asked.
	KnownModels *[]string `json:"knownModels,omitempty"`

	// LastError The last failure the instance log recorded, or null.
	LastError   interface{} `json:"lastError,omitempty"`
	LastSuccess *time.Time  `json:"lastSuccess,omitempty"`

	// MaxMessageLen How long a chat message, refinement or review note can be (200–4000, default 1000).
	MaxMessageLen *int `json:"maxMessageLen,omitempty"`

	// Model The model in force for the active provider.
	Model *string `json:"model,omitempty"`

	// Models Model per provider. Switching provider keeps them all.
	Models   *map[string]interface{} `json:"models,omitempty"`
	Provider *string                 `json:"provider,omitempty"`

	// Providers Every provider this build knows, and what each one needs.
	Providers *[]struct {
		ApiKey *bool `json:"apiKey,omitempty"`

		// BaseUrl Whether its endpoint is configurable.
		BaseUrl *bool `json:"baseUrl,omitempty"`

		// Connected Whether a credential is already filed for it.
		Connected      *bool   `json:"connected,omitempty"`
		DefaultModel   *string `json:"defaultModel,omitempty"`
		DeviceLogin    *bool   `json:"deviceLogin,omitempty"`
		Http           *bool   `json:"http,omitempty"`
		Id             *string `json:"id,omitempty"`
		KeyOptional    *bool   `json:"keyOptional,omitempty"`
		KeyPlaceholder *string `json:"keyPlaceholder,omitempty"`
		Label          *string `json:"label,omitempty"`

		// Runtime The runtime it spawns, when it spawns one.
		Runtime    *string `json:"runtime,omitempty"`
		SetupToken *bool   `json:"setupToken,omitempty"`
	} `json:"providers,omitempty"`

	// Recent The last 20 jobs, newest first. Counts and outcomes only, never contents.
	Recent *[]struct {
		At         *time.Time               `json:"at,omitempty"`
		ErrorClass *string                  `json:"errorClass,omitempty"`
		Kind       *string                  `json:"kind,omitempty"`
		Ms         *int                     `json:"ms,omitempty"`
		Outcome    *string                  `json:"outcome,omitempty"`
		Trigger    *AdminCoachRecentTrigger `json:"trigger,omitempty"`
	} `json:"recent,omitempty"`

	// Runtime The live check performed while answering this request.
	Runtime *struct {
		Error    *string `json:"error,omitempty"`
		NeedsKey *bool   `json:"needsKey,omitempty"`
		Ok       *bool   `json:"ok,omitempty"`
		Version  *string `json:"version,omitempty"`
	} `json:"runtime,omitempty"`

	// Unprivileged Whether the privilege drop can be performed. It fails closed: if `ok` is false no job runs at all, and the admin needs to hear that here rather than from a user.
	Unprivileged *struct {
		Dropped *bool   `json:"dropped,omitempty"`
		Ok      *bool   `json:"ok,omitempty"`
		Why     *string `json:"why,omitempty"`
	} `json:"unprivileged,omitempty"`
}

